package com.lebzlon.measurementtracker.entity;
import jakarta.persistence.*; import java.math.BigDecimal; import java.time.*;
@Entity @Table(name="ocr_tasks")
public class OcrTask { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(nullable=false) private Meter meter; @Column(nullable=false) private String imagePath; @Column(nullable=false) private Instant timestamp; @Enumerated(EnumType.STRING) @Column(nullable=false) private OcrTaskStatus status=OcrTaskStatus.NEW; @Column(nullable=false) private Instant createdAt=Instant.now(); private Instant processedAt; @Column(columnDefinition="TEXT") private String ocrRawText; private BigDecimal extractedValue; @Column(columnDefinition="TEXT") private String errorMessage;
public Long getId(){return id;} public Meter getMeter(){return meter;} public void setMeter(Meter m){this.meter=m;} public String getImagePath(){return imagePath;} public void setImagePath(String i){this.imagePath=i;} public Instant getTimestamp(){return timestamp;} public void setTimestamp(Instant t){this.timestamp=t;} public OcrTaskStatus getStatus(){return status;} public void setStatus(OcrTaskStatus s){this.status=s;} public Instant getCreatedAt(){return createdAt;} public Instant getProcessedAt(){return processedAt;} public void setProcessedAt(Instant p){this.processedAt=p;} public String getOcrRawText(){return ocrRawText;} public void setOcrRawText(String o){this.ocrRawText=o;} public BigDecimal getExtractedValue(){return extractedValue;} public void setExtractedValue(BigDecimal e){this.extractedValue=e;} public String getErrorMessage(){return errorMessage;} public void setErrorMessage(String e){this.errorMessage=e;} }
